const all = await query('com.example.type.task');
print('total tasks:', all.length);
const statuses = {};
for (const t of all) statuses[t.status] = (statuses[t.status] || 0) + 1;
print('statuses:', JSON.stringify(statuses));

const open = all.filter(t => t.status === 'open');
const results = [];
for (const t of open) {
  try {
    const score = await ops['com-example-operation-score']({ title: t.title });
    update(t, (o) => { o.priority = score; });
    results.push({ title: t.title, score });
  } catch (e) {
    print('FAILED for', t.title, '->', String(e));
  }
}
await flush();

const verify = await query('com.example.type.task', { status: 'open' });
for (const t of verify) print('stored:', t.title, '=>', t.priority);
results.sort((a, b) => b.score - a.score);
print('ranking:', JSON.stringify(results));
